style.css:
/* Page background */
body {
    background-color: #0a0a0a; /* Dark black */
    color: #00f5d4; /* Cyan green text */
    font-family: Arial, sans-serif;
    text-align: center;
    padding: 50px;
}

/* Glowing text effect */
h1, p {
    text-shadow: 0 0 5px #00f5d4,
                 0 0 10px #00f5d4,
                 0 0 20px #00f5d4,
                 0 0 40px #00f5d4;
}

/* Glowing button */
button {
    background-color: transparent;
    border: 2px solid #00f5d4;
    color: #00f5d4;
    padding: 10px 20px;
    font-size: 18px;
    cursor: pointer;
    text-shadow: 0 0 5px #00f5d4, 0 0 10px #00f5d4;
    box-shadow: 0 0 10px #00f5d4, 0 0 20px #00f5d4 inset;
    transition: 0.3s;
}

button:hover {
    background-color: #00f5d4;
    color: #0a0a0a;
}
